#!/bin/bashset -euo pipefail# Keycloak Vault Integration Entrypoint - Production Ready# This script configures and starts Keycloak in a production-ready mode.# It ensures all necessary configurations for database, cache, and proxy are set.LOG_PREFIX="[KEYCLOAK-PROD-ENTRYPOINT]"log_info() {    echo "$LOG_PREFIX INFO: $1" >&2}# --- Production Configuration ---log_info "Setting production environment for Keycloak..."# Database settingsexport KC_DB="postgres"export KC_DB_URL_HOST="purebliss-postgres"export KC_DB_URL_PORT="5432"export KC_DB_URL_DATABASE="keycloak"# Credentials will be passed as environment variables to the container# export KC_DB_USERNAME# export KC_DB_PASSWORD# Cache settings for Redisexport KC_CACHE="redis"export KC_CACHE_REDIS_HOST="purebliss-redis"export KC_CACHE_REDIS_PORT="6379"# Proxy settings for running behind Nginxexport KC_PROXY="edge"export KC_HTTP_ENABLED="true"export KC_HOSTNAME="dev.purebliss.app"export KC_HOSTNAME_STRICT="false"# Admin credentials will be passed as environment variables# export KEYCLOAK_ADMIN# export KEYCLOAK_ADMIN_PASSWORDlog_info "Database configured for: postgres://${KC_DB_USERNAME}@${KC_DB_URL_HOST}:${KC_DB_URL_PORT}/${KC_DB_URL_DATABASE}"log_info "Cache configured for Redis at: ${KC_CACHE_REDIS_HOST}:${KC_CACHE_REDIS_PORT}"log_info "Hostname set to: ${KC_HOSTNAME}"# The 'build' command is not needed when all config is passed via environment variables.# Keycloak will automatically configure itself on first start.log_info "Starting Keycloak in production mode..."exec /opt/keycloak/bin/kc.sh start --optimized
